CREATE TABLE `fun_admin_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '表id',
  `app_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '应用标识',
  `source_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT '来源类型',
  `source_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'core' COMMENT '来源标识',
  `admin_id` int unsigned NOT NULL DEFAULT '0' COMMENT '管理员ID',
  `username` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名',
  `method` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'HTTP方法',
  `controller` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '控制器',
  `action` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '动作',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '操作说明',
  `url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '请求地址',
  `post_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'POST数据',
  `get_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'GET数据',
  `header_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '脱敏请求头',
  `agent` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '头部信息',
  `ip` varchar(45) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '' COMMENT 'IP地址',
  `create_time` int unsigned NOT NULL DEFAULT '0' COMMENT '日志时间',
  `update_time` int DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否成功',
  `response_code` smallint unsigned NOT NULL DEFAULT '200' COMMENT 'HTTP响应状态码',
  `duration_ms` int unsigned NOT NULL DEFAULT '0' COMMENT '请求耗时毫秒',
  `request_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '请求追踪标识',
  `error_message` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '失败摘要',
  `delete_time` int DEFAULT '0' COMMENT '删除时间',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `admin_id` (`admin_id`),
  KEY `idx_admin_log_admin_time` (`admin_id`,`create_time`),
  KEY `idx_admin_log_app_time` (`app_name`,`create_time`),
  KEY `idx_admin_log_source_time` (`source_type`,`source_name`,`create_time`),
  KEY `idx_admin_log_status_time` (`status`,`create_time`),
  KEY `idx_admin_log_create_time` (`create_time`),
  KEY `idx_admin_log_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `fun_admin_menu` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `pid` int unsigned NOT NULL DEFAULT '0',
  `permission_id` int unsigned NOT NULL DEFAULT '0',
  `app_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'console' COMMENT 'ThinkPHP应用标识',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '菜单名称',
  `href` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `query` varchar(250) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `target` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '_self',
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `sort` int NOT NULL DEFAULT '999',
  `source_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system',
  `source_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` int NOT NULL DEFAULT '0',
  `update_time` int DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '999',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_menu_location` (`app_name`,`href`,`query`),
  KEY `idx_menu_tree` (`pid`,`status`,`sort`),
  KEY `idx_menu_permission` (`permission_id`),
  KEY `idx_menu_source` (`source_type`,`source_name`),
  KEY `idx_admin_menu_sort_order` (`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='后台菜单';
