CREATE TABLE `fun_ai_approval` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `conversation_id` bigint unsigned NOT NULL,
  `task_id` bigint unsigned NOT NULL,
  `tool_call_id` bigint unsigned NOT NULL,
  `requested_by` bigint unsigned NOT NULL,
  `decided_by` bigint unsigned DEFAULT NULL,
  `scope` enum('once','session_operation') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'once',
  `risk_reason` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `impact` json NOT NULL,
  `cas_version` bigint unsigned NOT NULL DEFAULT '0',
  `nonce` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `digest` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `operation` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mode_snapshot` enum('request_approval','agent_approval','full_access') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('pending','approved','consumed','denied','expired','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `request` json NOT NULL,
  `decision` json DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL,
  `decided_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_approval_nonce` (`nonce`),
  UNIQUE KEY `uk_ai_approval_digest` (`conversation_id`,`digest`),
  KEY `idx_ai_approval_conversation_status` (`conversation_id`,`status`),
  KEY `idx_ai_approval_task` (`task_id`),
  KEY `idx_ai_approval_tool_call` (`tool_call_id`),
  KEY `idx_ai_approval_requested_by` (`requested_by`),
  KEY `idx_ai_approval_decided_by` (`decided_by`),
  KEY `idx_ai_approval_deleted` (`deleted_at`),
  CONSTRAINT `fk_ai_approval_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `fun_ai_conversation` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_approval_decided_by` FOREIGN KEY (`decided_by`) REFERENCES `fun_admin` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_approval_requested_by` FOREIGN KEY (`requested_by`) REFERENCES `fun_admin` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_approval_task` FOREIGN KEY (`task_id`) REFERENCES `fun_ai_task` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_approval_tool_call` FOREIGN KEY (`tool_call_id`) REFERENCES `fun_ai_tool_call` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI approval';
CREATE TABLE `fun_ai_attachment` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `conversation_id` bigint unsigned NOT NULL,
  `admin_id` bigint unsigned NOT NULL,
  `message_id` bigint unsigned DEFAULT NULL,
  `kind` varchar(10) NOT NULL,
  `name` varchar(255) NOT NULL,
  `mime` varchar(64) NOT NULL,
  `size` int unsigned NOT NULL,
  `width` int unsigned DEFAULT NULL,
  `height` int unsigned DEFAULT NULL,
  `sha256` char(64) NOT NULL,
  `storage_path` char(64) NOT NULL,
  `expires_at` datetime NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_storage_path` (`storage_path`),
  KEY `idx_owner_conversation` (`admin_id`,`conversation_id`),
  KEY `idx_message` (`message_id`),
  KEY `idx_draft_expiry` (`message_id`,`expires_at`,`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `fun_ai_change_set` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `conversation_id` bigint unsigned NOT NULL,
  `task_id` bigint unsigned NOT NULL,
  `approval_id` bigint unsigned DEFAULT NULL,
  `final_approval_id` bigint unsigned DEFAULT NULL,
  `created_by` bigint unsigned NOT NULL,
  `applied_by` bigint unsigned DEFAULT NULL,
  `idempotency_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `digest` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `base_digest` char(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `plan_digest` char(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `patch_path` varchar(1024) COLLATE utf8mb4_unicode_ci NOT NULL,
  `patch_sha256` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `base_file_hashes` json NOT NULL,
  `selection` json DEFAULT NULL,
  `added_count` int unsigned NOT NULL DEFAULT '0',
  `modified_count` int unsigned NOT NULL DEFAULT '0',
  `deleted_count` int unsigned NOT NULL DEFAULT '0',
  `renamed_count` int unsigned NOT NULL DEFAULT '0',
  `test_status` enum('pending','running','passed','failed','skipped') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `test_result` json DEFAULT NULL,
  `security_status` enum('pending','running','passed','failed','skipped') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `security_result` json DEFAULT NULL,
  `transaction_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recovery_status` enum('none','recovery_required','recovering','recovered','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `recovery_version` int unsigned NOT NULL DEFAULT '0',
  `status` enum('proposed','approved','applying','applied','rejected','failed','conflict','recovery_required') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'proposed',
  `manifest` json NOT NULL,
  `summary` json DEFAULT NULL,
  `base_revision` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `applied_revision` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `applied_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_change_set_idempotency` (`conversation_id`,`idempotency_key`),
  UNIQUE KEY `uk_ai_change_set_digest` (`conversation_id`,`digest`),
  UNIQUE KEY `uk_ai_change_set_transaction` (`transaction_id`),
  KEY `idx_ai_change_set_conversation_status` (`conversation_id`,`status`),
  KEY `idx_ai_change_set_task` (`task_id`),
  KEY `idx_ai_change_set_approval` (`approval_id`),
  KEY `idx_ai_change_set_final_approval` (`final_approval_id`),
  KEY `idx_ai_change_set_created_by` (`created_by`),
  KEY `idx_ai_change_set_applied_by` (`applied_by`),
  KEY `idx_ai_change_set_deleted` (`deleted_at`),
  KEY `idx_ai_change_set_owner_status` (`created_by`,`conversation_id`,`status`,`id`),
  CONSTRAINT `fk_ai_change_set_applied_by` FOREIGN KEY (`applied_by`) REFERENCES `fun_admin` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_change_set_approval` FOREIGN KEY (`approval_id`) REFERENCES `fun_ai_approval` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_change_set_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `fun_ai_conversation` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_change_set_created_by` FOREIGN KEY (`created_by`) REFERENCES `fun_admin` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_change_set_final_approval` FOREIGN KEY (`final_approval_id`) REFERENCES `fun_ai_approval` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_change_set_task` FOREIGN KEY (`task_id`) REFERENCES `fun_ai_task` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI change set';
CREATE TABLE `fun_ai_configuration_profile` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `admin_id` bigint unsigned NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `configuration` json NOT NULL,
  `secret_ciphertext` text COLLATE utf8mb4_unicode_ci,
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `default_admin_id` bigint unsigned GENERATED ALWAYS AS ((case when (`is_default` = 1) then `admin_id` else NULL end)) STORED,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_profile_default` (`default_admin_id`),
  KEY `idx_ai_profile_admin` (`admin_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `fun_ai_conversation` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `admin_id` bigint unsigned NOT NULL,
  `group_id` bigint unsigned DEFAULT NULL,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `status` enum('draft','planning','awaiting_approval','running','reviewing','applying','completed','paused','cancelled','failed','conflict','recovery_required') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `is_archived` tinyint(1) NOT NULL DEFAULT '0',
  `is_unread` tinyint(1) NOT NULL DEFAULT '0',
  `approval_mode` enum('request_approval','agent_approval','full_access') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'request_approval',
  `provider` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `model` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `context` json DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `profile_id` bigint unsigned DEFAULT NULL,
  `reasoning_effort` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_conversation_uuid` (`uuid`),
  KEY `idx_ai_conversation_admin_status` (`admin_id`,`status`),
  KEY `idx_ai_conversation_deleted` (`deleted_at`),
  KEY `idx_ai_conversation_group` (`admin_id`,`group_id`,`is_archived`,`updated_at`),
  KEY `fk_ai_conversation_group` (`group_id`),
  KEY `idx_ai_conversation_profile` (`profile_id`),
  CONSTRAINT `fk_ai_conversation_admin` FOREIGN KEY (`admin_id`) REFERENCES `fun_admin` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_conversation_group` FOREIGN KEY (`group_id`) REFERENCES `fun_ai_conversation_group` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI conversation';
CREATE TABLE `fun_ai_conversation_group` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `admin_id` bigint unsigned NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `active_name` varchar(100) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`deleted_at` is null) then `name` else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_conversation_group_active_name` (`admin_id`,`active_name`),
  KEY `idx_ai_conversation_group_owner` (`admin_id`,`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `fun_ai_message` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `conversation_id` bigint unsigned NOT NULL,
  `parent_id` bigint unsigned DEFAULT NULL,
  `sequence` int unsigned NOT NULL,
  `role` enum('system','user','assistant','tool') COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` json NOT NULL,
  `metadata` json DEFAULT NULL,
  `usage` json DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `idempotency_key` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `payload_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_message_sequence` (`conversation_id`,`sequence`),
  UNIQUE KEY `uk_ai_message_client_key` (`conversation_id`,`idempotency_key`),
  KEY `idx_ai_message_conversation_sequence` (`conversation_id`,`sequence`),
  KEY `idx_ai_message_parent` (`parent_id`),
  KEY `idx_ai_message_deleted` (`deleted_at`),
  CONSTRAINT `fk_ai_message_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `fun_ai_conversation` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_message_parent` FOREIGN KEY (`parent_id`) REFERENCES `fun_ai_message` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI message';
CREATE TABLE `fun_ai_outbox` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `aggregate_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `aggregate_id` bigint unsigned NOT NULL,
  `event_type` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `idempotency_key` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` json NOT NULL,
  `status` enum('pending','processing','dispatched','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `lease_owner` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lease_expires_at` datetime DEFAULT NULL,
  `attempts` int unsigned NOT NULL DEFAULT '0',
  `available_at` datetime NOT NULL,
  `last_error` text COLLATE utf8mb4_unicode_ci,
  `dispatched_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_outbox_idempotency` (`idempotency_key`),
  KEY `idx_ai_outbox_dispatch` (`status`,`available_at`,`id`),
  KEY `idx_ai_outbox_claim` (`status`,`available_at`,`lease_expires_at`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `fun_ai_stream_nonce` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
