  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_stream_nonce` (`nonce_hash`),
  KEY `idx_ai_stream_nonce_expiry` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `fun_ai_task` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
