  `message_id` bigint unsigned DEFAULT NULL,
  `parent_id` bigint unsigned DEFAULT NULL,
  `change_set_id` bigint unsigned DEFAULT NULL,
  `idempotency_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `operation_token` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('chat','crud','code_change','fix','test','migration') COLLATE utf8mb4_unicode_ci NOT NULL,
  `stage` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `status` enum('pending','running','resume_pending','succeeded','failed','cancelled','paused','recovery_required') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `approval_mode` enum('request_approval','agent_approval','full_access') COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `model` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `container_task_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sandbox_volume` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `workspace_path` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sandbox_status` enum('pending','created','running','exported','cleaning','cleaned','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `sandbox_retained` tinyint(1) NOT NULL DEFAULT '0',
  `heartbeat_at` datetime DEFAULT NULL,
  `max_rounds` int unsigned NOT NULL DEFAULT '0',
  `timeout_seconds` int unsigned NOT NULL DEFAULT '0',
  `max_cost` decimal(12,4) NOT NULL DEFAULT '0.0000',
  `input_token_budget` bigint unsigned NOT NULL DEFAULT '0',
  `output_token_budget` bigint unsigned NOT NULL DEFAULT '0',
  `total_token_budget` bigint unsigned NOT NULL DEFAULT '0',
  `usage` json DEFAULT NULL,
  `input` json DEFAULT NULL,
  `output` json DEFAULT NULL,
  `error` json DEFAULT NULL,
  `result_summary` text COLLATE utf8mb4_unicode_ci,
  `test_result` json DEFAULT NULL,
  `recovery_status` enum('none','recovery_required','recovering','recovered','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `cleanup_at` datetime DEFAULT NULL,
  `cleanup_lease_owner` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cleanup_lease_expires_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_task_idempotency` (`conversation_id`,`idempotency_key`),
  UNIQUE KEY `uk_ai_task_operation_token` (`operation_token`),
  KEY `idx_ai_task_conversation_status` (`conversation_id`,`status`),
  KEY `idx_ai_task_message` (`message_id`),
  KEY `idx_ai_task_parent` (`parent_id`),
  KEY `idx_ai_task_change_set` (`change_set_id`),
  KEY `idx_ai_task_container` (`container_task_id`),
  KEY `idx_ai_task_deleted` (`deleted_at`),
  KEY `idx_ai_task_sandbox_status` (`sandbox_status`,`updated_at`),
  KEY `idx_ai_task_sandbox_lease` (`sandbox_status`,`sandbox_retained`,`heartbeat_at`,`completed_at`),
  KEY `idx_ai_task_cleanup_candidate` (`status`,`sandbox_status`,`completed_at`,`sandbox_retained`),
  CONSTRAINT `fk_ai_task_change_set` FOREIGN KEY (`change_set_id`) REFERENCES `fun_ai_change_set` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_task_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `fun_ai_conversation` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_task_message` FOREIGN KEY (`message_id`) REFERENCES `fun_ai_message` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_task_parent` FOREIGN KEY (`parent_id`) REFERENCES `fun_ai_task` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI task';
CREATE TABLE `fun_ai_task_event` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `task_id` bigint unsigned NOT NULL,
  `sequence` bigint unsigned NOT NULL,
