  `payload` json NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_task_event_sequence` (`task_id`,`sequence`),
  KEY `idx_ai_task_event_cursor` (`task_id`,`id`),
  CONSTRAINT `fk_ai_task_event_task` FOREIGN KEY (`task_id`) REFERENCES `fun_ai_task` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `fun_ai_tool_call` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `conversation_id` bigint unsigned NOT NULL,
  `task_id` bigint unsigned NOT NULL,
  `message_id` bigint unsigned DEFAULT NULL,
  `approval_id` bigint unsigned DEFAULT NULL,
  `idempotency_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tool_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `operation` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `risk_level` enum('low','medium','high','critical') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'low',
  `status` enum('pending','awaiting_approval','running','succeeded','failed','denied') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `redacted_arguments` json NOT NULL,
  `approval_decision` enum('not_required','pending','approved','denied','expired','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'not_required',
  `result` json DEFAULT NULL,
  `error` json DEFAULT NULL,
  `exit_code` int DEFAULT NULL,
  `stdout_summary` text COLLATE utf8mb4_unicode_ci,
  `stdout_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stdout_path` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stderr_summary` text COLLATE utf8mb4_unicode_ci,
  `stderr_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stderr_path` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `duration_ms` bigint unsigned DEFAULT NULL,
  `side_effects` json DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_tool_call_idempotency` (`conversation_id`,`idempotency_key`),
  KEY `idx_ai_tool_call_task_status` (`task_id`,`status`),
  KEY `idx_ai_tool_call_conversation` (`conversation_id`,`created_at`),
  KEY `idx_ai_tool_call_message` (`message_id`),
  KEY `idx_ai_tool_call_approval` (`approval_id`),
  CONSTRAINT `fk_ai_tool_call_approval` FOREIGN KEY (`approval_id`) REFERENCES `fun_ai_approval` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_tool_call_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `fun_ai_conversation` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_tool_call_message` FOREIGN KEY (`message_id`) REFERENCES `fun_ai_message` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_tool_call_task` FOREIGN KEY (`task_id`) REFERENCES `fun_ai_task` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Immutable AI tool call security record';
CREATE TABLE `fun_application_assignment` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `application_id` bigint unsigned NOT NULL,
  `subject_type` enum('all','user','department','role') COLLATE utf8mb4_unicode_ci NOT NULL,
  `subject_id` bigint unsigned DEFAULT NULL,
  `subject_key` bigint unsigned GENERATED ALWAYS AS (ifnull(`subject_id`,0)) STORED,
  `effect` enum('allow','deny') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'allow',
  `status` tinyint NOT NULL DEFAULT '1',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_application_assignment` (`tenant_id`,`application_id`,`subject_type`,`subject_key`,`effect`),
  KEY `idx_application_assignment_subject` (`tenant_id`,`subject_type`,`subject_id`,`status`),
  KEY `idx_application_assignment_app` (`application_id`),
  CONSTRAINT `fk_application_assignment_app_tenant` FOREIGN KEY (`tenant_id`, `application_id`) REFERENCES `fun_enterprise_application` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_application_assignment_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `fun_identity_tenant` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_application_assignment_subject` CHECK ((((`subject_type` = _utf8mb4'all') and (`subject_id` is null)) or ((`subject_type` <> _utf8mb4'all') and (`subject_id` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='企业应用访问范围';
CREATE TABLE `fun_application_database` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
