CREATE TABLE `fun_attach` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `admin_id` int NOT NULL DEFAULT '0' COMMENT '管理员id',
  `member_id` int NOT NULL DEFAULT '0' COMMENT '用户表id',
  `group_id` int NOT NULL DEFAULT '1' COMMENT '分组id',
  `original_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件原名',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件名',
  `storage_key` varchar(768) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '存储对象键',
  `thumb` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '缩略图',
  `path` varchar(768) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '访问路径',
  `url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '完整地址',
  `ext` varchar(20) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT '后缀',
  `size` int DEFAULT '0' COMMENT '大小',
  `width` int unsigned NOT NULL DEFAULT '0' COMMENT '宽度',
  `height` int unsigned NOT NULL DEFAULT '0' COMMENT '高度',
  `md5` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MD5',
  `sha1` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'sha1 散列值',
  `mime` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MIME',
  `duration` int unsigned NOT NULL DEFAULT '0' COMMENT '音视频时长秒',
  `driver` varchar(30) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'local' COMMENT '存储驱动',
  `create_time` int DEFAULT '0',
  `update_time` int DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `sort` int NOT NULL DEFAULT '50',
  `delete_time` int DEFAULT '0' COMMENT '删除时间',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '50',
  PRIMARY KEY (`id`),
  KEY `admin_id` (`admin_id`),
  KEY `member_id` (`member_id`),
  KEY `md5` (`md5`),
  KEY `idx_attach_group` (`group_id`),
  KEY `idx_attach_path` (`path`),
  KEY `idx_attach_deleted_at` (`deleted_at`),
  KEY `idx_attach_sort_order` (`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
