  UNIQUE KEY `uk_config_group_name` (`name`),
  KEY `name` (`name`),
  KEY `idx_config_group_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
