CREATE TABLE `fun_crud_generation` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `business_module_id` bigint unsigned DEFAULT NULL,
  `form_id` bigint unsigned DEFAULT NULL,
  `binding_status` varchar(20) NOT NULL DEFAULT 'unbound',
  `generation_mode` varchar(32) NOT NULL DEFAULT 'full',
  `transaction_id` varchar(64) DEFAULT NULL,
  `plan_digest` char(64) DEFAULT NULL,
  `recovery_status` varchar(32) NOT NULL DEFAULT 'none',
  `operation` varchar(20) NOT NULL,
  `operation_key` varchar(191) DEFAULT NULL,
  `superseded_by_id` bigint unsigned DEFAULT NULL,
  `status` varchar(32) NOT NULL,
  `connection_name` varchar(64) NOT NULL DEFAULT '',
  `table_name` varchar(190) NOT NULL DEFAULT '',
  `definition_hash` char(64) NOT NULL,
  `definition` json DEFAULT NULL,
  `manifest` json DEFAULT NULL,
  `result` json DEFAULT NULL,
  `error` json DEFAULT NULL,
  `failure_code` varchar(64) DEFAULT NULL,
  `actor` varchar(100) DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `failed_at` datetime DEFAULT NULL,
  `recovered_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_crud_generation_operation_key` (`operation_key`),
  KEY `idx_crud_generation_table` (`connection_name`,`table_name`),
  KEY `idx_crud_generation_created_at` (`created_at`),
  KEY `idx_crud_generation_business_module` (`business_module_id`,`binding_status`),
  KEY `idx_crud_generation_form` (`form_id`,`binding_status`),
  KEY `idx_crud_generation_transaction` (`transaction_id`),
  KEY `idx_crud_generation_plan_digest` (`plan_digest`),
  KEY `idx_crud_generation_status_recovery` (`status`,`recovery_status`),
  KEY `idx_crud_generation_superseded_by` (`superseded_by_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='CRUD 生成审计';
CREATE TABLE `fun_department` (
