CREATE TABLE `fun_enterprise_application` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `public_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `icon` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `visibility` enum('private','tenant','public') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'tenant',
  `runtime_type` enum('internal','plugin','standalone') COLLATE utf8mb4_unicode_ci NOT NULL,
  `database_mode` enum('shared','dedicated','external') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'shared',
  `launch_url` varchar(2048) COLLATE utf8mb4_unicode_ci NOT NULL,
  `base_url` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `owner` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `owner_identity_user_id` bigint unsigned DEFAULT NULL,
  `status` enum('draft','published','disabled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `logo_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand_config` json DEFAULT NULL,
  `oauth_config` json DEFAULT NULL,
  `claim_policy` json DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_enterprise_application_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_enterprise_application_public` (`tenant_id`,`public_id`),
  UNIQUE KEY `uk_enterprise_application_code` (`tenant_id`,`code`),
  KEY `idx_enterprise_application_status` (`tenant_id`,`status`,`deleted_at`),
  KEY `idx_enterprise_application_owner_identity_user` (`owner_identity_user_id`),
  CONSTRAINT `fk_enterprise_application_owner_identity_user` FOREIGN KEY (`owner_identity_user_id`) REFERENCES `fun_identity_user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_enterprise_application_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `fun_identity_tenant` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='企业应用目录';
