CREATE TABLE `fun_oauth_authorization` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `client_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `transaction_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `csrf_token_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `redirect_uri` varchar(2048) COLLATE utf8mb4_unicode_ci NOT NULL,
  `redirect_uri_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `state` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nonce` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `code_challenge` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code_challenge_method` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'S256',
  `subject_type` enum('user') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'user',
  `status` enum('pending','approved','denied','completed','expired','revoked') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `auth_time` datetime DEFAULT NULL,
  `session_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `oidc_session_id` bigint unsigned DEFAULT NULL,
  `client_session_id` bigint unsigned DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  `decided_at` datetime DEFAULT NULL,
  `interaction_consumed_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oauth_authorization_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_oauth_authorization_transaction` (`transaction_hash`),
  KEY `idx_oauth_authorization_client_status` (`tenant_id`,`client_id`,`status`,`expires_at`),
  KEY `idx_oauth_authorization_user` (`tenant_id`,`user_id`),
  KEY `fk_oauth_authorization_user` (`user_id`),
  KEY `idx_oauth_authorization_oidc_session` (`tenant_id`,`oidc_session_id`,`client_session_id`),
  CONSTRAINT `fk_oauth_authorization_client_tenant` FOREIGN KEY (`tenant_id`, `client_id`) REFERENCES `fun_oauth_client` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_authorization_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `fun_identity_tenant` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_authorization_user` FOREIGN KEY (`user_id`) REFERENCES `fun_identity_user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_oauth_authorization_pkce` CHECK ((`code_challenge_method` = _utf8mb4'S256'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OAuth 授权事务';
CREATE TABLE `fun_oauth_authorization_code` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `authorization_id` bigint unsigned NOT NULL,
  `client_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `code_prefix` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `redirect_uri_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code_challenge` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nonce` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subject_type` enum('user') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'user',
  `expires_at` datetime NOT NULL,
  `consumed_at` datetime DEFAULT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oauth_authorization_code_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_oauth_authorization_code_hash` (`code_hash`),
  KEY `idx_oauth_authorization_code_consume` (`tenant_id`,`client_id`,`code_prefix`,`consumed_at`,`revoked_at`,`expires_at`),
  KEY `idx_oauth_authorization_code_user` (`tenant_id`,`user_id`),
  KEY `fk_oauth_authorization_code_authorization` (`tenant_id`,`authorization_id`),
  KEY `fk_oauth_authorization_code_user` (`user_id`),
  CONSTRAINT `fk_oauth_authorization_code_authorization` FOREIGN KEY (`tenant_id`, `authorization_id`) REFERENCES `fun_oauth_authorization` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_authorization_code_client` FOREIGN KEY (`tenant_id`, `client_id`) REFERENCES `fun_oauth_client` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_authorization_code_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `fun_identity_tenant` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_authorization_code_user` FOREIGN KEY (`user_id`) REFERENCES `fun_identity_user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OAuth authorization code 哈希';
CREATE TABLE `fun_oauth_authorization_scope` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `authorization_id` bigint unsigned NOT NULL,
  `scope_id` bigint unsigned NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oauth_authorization_scope` (`tenant_id`,`authorization_id`,`scope_id`),
  KEY `idx_oauth_authorization_scope_scope` (`tenant_id`,`scope_id`),
  CONSTRAINT `fk_oauth_authorization_scope_authorization` FOREIGN KEY (`tenant_id`, `authorization_id`) REFERENCES `fun_oauth_authorization` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_authorization_scope_scope` FOREIGN KEY (`tenant_id`, `scope_id`) REFERENCES `fun_scope` (`tenant_id`, `id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_authorization_scope_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `fun_identity_tenant` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OAuth 授权 scope';
CREATE TABLE `fun_oauth_client` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `application_id` bigint unsigned NOT NULL,
  `client_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `client_type` enum('public','confidential','machine') COLLATE utf8mb4_unicode_ci NOT NULL,
  `token_endpoint_auth_method` enum('none','client_secret_basic') COLLATE utf8mb4_unicode_ci NOT NULL,
  `require_pkce` tinyint NOT NULL DEFAULT '0',
  `subject_type` enum('public','pairwise') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'public',
  `sector_identifier` varchar(253) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `allowed_claims` json DEFAULT NULL,
  `backchannel_logout_uri` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','disabled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oauth_client_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_oauth_client_client_id` (`client_id`),
  UNIQUE KEY `uk_oauth_client_application_name` (`tenant_id`,`application_id`,`name`),
  KEY `idx_oauth_client_application` (`tenant_id`,`application_id`,`status`),
  CONSTRAINT `fk_oauth_client_application_tenant` FOREIGN KEY (`tenant_id`, `application_id`) REFERENCES `fun_enterprise_application` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_client_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `fun_identity_tenant` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_oauth_client_policy` CHECK ((((`client_type` = _utf8mb4'public') and (`token_endpoint_auth_method` = _utf8mb4'none') and (`require_pkce` = 1)) or ((`client_type` in (_utf8mb4'confidential',_utf8mb4'machine')) and (`token_endpoint_auth_method` = _utf8mb4'client_secret_basic'))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OAuth 客户端';
CREATE TABLE `fun_oauth_token` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `client_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `token_type` enum('access','refresh') COLLATE utf8mb4_unicode_ci NOT NULL,
  `token_prefix` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `token_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `family_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parent_id` bigint unsigned DEFAULT NULL,
  `generation` int unsigned NOT NULL DEFAULT '0',
  `subject_type` enum('user','client') COLLATE utf8mb4_unicode_ci NOT NULL,
  `authorization_id` bigint unsigned DEFAULT NULL,
  `session_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `password_version` bigint unsigned DEFAULT NULL,
  `session_version` bigint unsigned DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  `consumed_at` datetime DEFAULT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oauth_token_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_oauth_token_hash` (`token_hash`),
  KEY `idx_oauth_token_lookup` (`token_prefix`,`token_type`,`revoked_at`,`expires_at`),
  KEY `idx_oauth_token_client` (`tenant_id`,`client_id`,`token_type`,`revoked_at`),
  KEY `idx_oauth_token_user` (`tenant_id`,`user_id`,`revoked_at`),
  KEY `idx_oauth_token_family` (`tenant_id`,`family_id`,`generation`,`revoked_at`),
  KEY `idx_oauth_token_parent` (`parent_id`),
  KEY `fk_oauth_token_user` (`user_id`),
  KEY `fk_oauth_token_authorization` (`tenant_id`,`authorization_id`),
  KEY `idx_oauth_token_bearer` (`token_hash`,`token_type`,`revoked_at`,`expires_at`,`tenant_id`,`client_id`),
  CONSTRAINT `fk_oauth_token_authorization` FOREIGN KEY (`tenant_id`, `authorization_id`) REFERENCES `fun_oauth_authorization` (`tenant_id`, `id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_token_client` FOREIGN KEY (`tenant_id`, `client_id`) REFERENCES `fun_oauth_client` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_token_parent` FOREIGN KEY (`parent_id`) REFERENCES `fun_oauth_token` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_token_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `fun_identity_tenant` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_token_user` FOREIGN KEY (`user_id`) REFERENCES `fun_identity_user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `ck_oauth_token_subject` CHECK ((((`subject_type` = _utf8mb4'user') and (`user_id` is not null)) or ((`subject_type` = _utf8mb4'client') and (`user_id` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OAuth opaque token 哈希与 rotation family';
CREATE TABLE `fun_oauth_token_scope` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `token_id` bigint unsigned NOT NULL,
  `scope_id` bigint unsigned NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oauth_token_scope` (`tenant_id`,`token_id`,`scope_id`),
  KEY `idx_oauth_token_scope_scope` (`tenant_id`,`scope_id`),
  CONSTRAINT `fk_oauth_token_scope_scope` FOREIGN KEY (`tenant_id`, `scope_id`) REFERENCES `fun_scope` (`tenant_id`, `id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_token_scope_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `fun_identity_tenant` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_oauth_token_scope_token` FOREIGN KEY (`tenant_id`, `token_id`) REFERENCES `fun_oauth_token` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OAuth token scope';
CREATE TABLE `fun_oidc_client_session` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `oidc_session_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `client_id` bigint unsigned NOT NULL,
  `sid` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('active','ended') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `last_authorized_at` datetime NOT NULL,
  `ended_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oidc_client_session_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_oidc_client_session_sid` (`sid`),
  KEY `idx_oidc_client_session_user` (`tenant_id`,`user_id`,`status`),
  KEY `idx_oidc_client_session_op_fk` (`tenant_id`,`oidc_session_id`),
  KEY `idx_oidc_client_session_client_fk` (`tenant_id`,`client_id`),
  KEY `idx_oidc_client_session_binding` (`tenant_id`,`oidc_session_id`,`client_id`,`status`),
  CONSTRAINT `fk_oidc_client_session_client` FOREIGN KEY (`tenant_id`, `client_id`) REFERENCES `fun_oauth_client` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_oidc_client_session_op` FOREIGN KEY (`tenant_id`, `oidc_session_id`) REFERENCES `fun_oidc_session` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_oidc_client_session_user` FOREIGN KEY (`tenant_id`, `user_id`) REFERENCES `fun_identity_user` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OIDC RP 客户端会话';
CREATE TABLE `fun_oidc_session` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `sid` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `session_token_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `auth_time` datetime NOT NULL,
  `last_seen_at` datetime NOT NULL,
  `expires_at` datetime NOT NULL,
  `password_version` bigint unsigned NOT NULL,
  `session_version` bigint unsigned NOT NULL,
  `status` enum('active','ended') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `ended_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oidc_session_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_oidc_session_sid` (`sid`),
  UNIQUE KEY `uk_oidc_session_token_hash` (`session_token_hash`),
  KEY `idx_oidc_session_user_active` (`tenant_id`,`user_id`,`status`,`expires_at`),
  CONSTRAINT `fk_oidc_session_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `fun_identity_tenant` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_oidc_session_user` FOREIGN KEY (`tenant_id`, `user_id`) REFERENCES `fun_identity_user` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OIDC OP 登录会话';
CREATE TABLE `fun_oidc_signing_key` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `kid` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `algorithm` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RS256',
  `status` enum('pending','active','retiring','retired') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `private_key_ref` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL,
  `public_jwk` json NOT NULL,
  `activated_at` datetime DEFAULT NULL,
  `retired_at` datetime DEFAULT NULL,
  `publish_until` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oidc_signing_key_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_oidc_signing_key_kid` (`tenant_id`,`kid`),
  KEY `idx_oidc_signing_key_publish` (`tenant_id`,`status`,`publish_until`),
  CONSTRAINT `fk_oidc_signing_key_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `fun_identity_tenant` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_oidc_signing_key_algorithm` CHECK ((`algorithm` = _utf8mb4'RS256'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OIDC RS256 签名密钥元数据';
CREATE TABLE `fun_permission` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `pid` int unsigned NOT NULL DEFAULT '0',
  `app_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'console' COMMENT 'ThinkPHP应用标识',
  `code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `obj` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `act` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '权限名称',
  `resource_type` enum('group','route','capability') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'route',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `is_public` tinyint(1) NOT NULL DEFAULT '0',
  `sort` int NOT NULL DEFAULT '999',
  `source_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system',
  `source_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` int NOT NULL DEFAULT '0',
  `update_time` int DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '999',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_permission_code` (`code`),
  KEY `idx_permission_tree` (`pid`,`status`,`sort`),
  KEY `idx_permission_resource` (`obj`,`act`),
  KEY `idx_permission_source` (`source_type`,`source_name`),
  KEY `idx_permission_sort_order` (`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='权限资源目录';
