CREATE TABLE `fun_permission_field` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `permission_id` int unsigned NOT NULL COMMENT '所属功能权限资源ID',
  `resource` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '稳定资源标识',
  `field` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务端字段名',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段显示名称',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` int unsigned NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_permission_field_resource_field` (`resource`,`field`),
  KEY `idx_permission_field_permission` (`permission_id`,`status`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='权限资源字段白名单';
CREATE TABLE `fun_plugin` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(250) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `thumb` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '封面',
  `group` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '组别',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '插件描述',
  `author` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '作者',
  `version` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '版本号',
  `package_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前包 SHA-256',
  `code_version` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '已部署代码版本',
  `source` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'local' COMMENT '包来源',
  `db_version` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '插件数据库版本',
  `migration_pending` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否待执行数据库迁移',
  `last_error` text COLLATE utf8mb4_unicode_ci COMMENT '最近一次生命周期错误',
  `error_stage` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败阶段',
  `recovery_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '人工恢复路径',
  `needs_reinstall` tinyint(1) NOT NULL DEFAULT '0' COMMENT '必须重新安装',
  `installed_at` int unsigned DEFAULT NULL COMMENT '安装时间',
  `requires` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '需求版本(废弃,见plugin.json)',
  `website` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '网址',
  `manifest` json DEFAULT NULL COMMENT 'plugin.json 契约快照',
  `is_hook` tinyint(1) DEFAULT '0' COMMENT '钩子[0:不支持;1:支持]',
  `config` longtext COLLATE utf8mb4_unicode_ci COMMENT '插件配置',
  `status` tinyint DEFAULT '1' COMMENT '状态[-1:删除;0:禁用;1启用]',
  `lifecycle_state` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'disabled' COMMENT '显式生命周期状态',
  `state_changed_at` int DEFAULT NULL COMMENT '状态最后变更时间',
  `operation_token` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生命周期操作令牌',
  `create_time` int DEFAULT '0' COMMENT '创建时间',
  `update_time` int DEFAULT '0' COMMENT '修改时间',
  `delete_time` int DEFAULT '0' COMMENT '删除时间',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plugin_code` (`code`),
  KEY `name` (`code`),
  KEY `idx_plugin_lifecycle_state` (`lifecycle_state`),
  KEY `idx_plugin_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公用_插件表';
CREATE TABLE `fun_plugin_operation` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plugin_code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `operation` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'install/update',
  `stage` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'complete' COMMENT '生命周期阶段',
  `progress` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '阶段进度',
  `from_version` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `to_version` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `source` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'local/cloud',
  `package_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `result` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'success/failed',
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `recovery_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '人工恢复路径',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `create_time` int unsigned NOT NULL DEFAULT '0',
  `update_time` int unsigned DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `operation_token` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联生命周期操作令牌',
  PRIMARY KEY (`id`),
  KEY `idx_plugin_operation_name_time` (`plugin_code`,`create_time`),
  KEY `idx_plugin_operation_result` (`result`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='插件生命周期操作历史';
CREATE TABLE `fun_plugin_resource` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plugin_code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'file',
  `publication_unit` varchar(190) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operation_token` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sha256` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tree_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plugin_resource_target_path` (`target_path`),
  KEY `idx_plugin_resource_owner` (`plugin_code`,`version`),
  KEY `idx_plugin_resource_publication_unit` (`plugin_code`,`resource_type`,`publication_unit`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='插件发布资源归属';
CREATE TABLE `fun_plugin_version_history` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plugin_code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `max_db_version` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '此代码已知最高数据库版本',
  `source` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'local/cloud',
  `package_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实际插件包 SHA-256',
  `signature_algorithm` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `signature_verified` tinyint(1) NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `create_time` int unsigned NOT NULL DEFAULT '0',
  `update_time` int unsigned DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `package_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'runtime 私有历史包路径',
  PRIMARY KEY (`id`),
  KEY `idx_plugin_version_name_time` (`plugin_code`,`create_time`),
  KEY `idx_plugin_version_hash` (`package_hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='插件包版本历史';
CREATE TABLE `fun_provinces` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '栏目名',
  `pid` int NOT NULL DEFAULT '0' COMMENT '父栏目',
  `short_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '缩写',
  `areacode` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '区域编码',
  `zipcode` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '邮政编码',
  `pinyin` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '拼音',
  `lng` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '经度',
  `lat` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '纬度',
  `level` tinyint NOT NULL DEFAULT '1' COMMENT '级别',
  `sort` tinyint unsigned DEFAULT '0' COMMENT '排序',
  `delete_time` int DEFAULT '0' COMMENT '删除时间',
  `deleted_at` datetime DEFAULT NULL,
  `sort_order` tinyint unsigned DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `parentid` (`pid`),
  KEY `idx_provinces_deleted_at` (`deleted_at`),
  KEY `idx_provinces_sort_order` (`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公用_省市区记录表';
