CREATE TABLE `fun_redirect_uri` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `client_id` bigint unsigned NOT NULL,
  `uri_type` enum('authorization_callback','post_logout') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'authorization_callback',
  `redirect_uri` varchar(2048) COLLATE utf8mb4_unicode_ci NOT NULL,
  `uri_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_redirect_uri_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_redirect_uri_exact` (`tenant_id`,`client_id`,`uri_type`,`uri_hash`),
  KEY `idx_redirect_uri_client` (`tenant_id`,`client_id`,`status`),
  CONSTRAINT `fk_redirect_uri_client_tenant` FOREIGN KEY (`tenant_id`, `client_id`) REFERENCES `fun_oauth_client` (`tenant_id`, `id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_redirect_uri_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `fun_identity_tenant` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OAuth 精确重定向 URI';
CREATE TABLE `fun_region` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `pid` int NOT NULL DEFAULT '0',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `short_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `area_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `zip_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `pinyin` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `longitude` decimal(10,6) DEFAULT NULL,
  `latitude` decimal(10,6) DEFAULT NULL,
  `level` tinyint NOT NULL DEFAULT '1',
  `sort_order` int unsigned NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
