CREATE TABLE `fun_upgrade_manifest` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `manifest_id` char(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `payload` json NOT NULL,
  `expires_at` datetime NOT NULL,
  `consumed_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_upgrade_manifest_id` (`manifest_id`),
  KEY `idx_upgrade_manifest_expiry` (`expires_at`,`consumed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='一次性可信升级 manifest';
CREATE TABLE `fun_upgrade_task` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `idempotency_token` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `manifest_id` char(48) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `from_version` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `to_version` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `stage` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `progress` tinyint unsigned NOT NULL DEFAULT '0',
  `package_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `backup_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `backup_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `db_backup_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `db_backup_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `db_backup_schema` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `metadata` json DEFAULT NULL,
  `active_slot` tinyint unsigned DEFAULT NULL,
  `lease_expires_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_upgrade_task_token` (`idempotency_token`),
  UNIQUE KEY `uk_upgrade_task_active` (`active_slot`),
  KEY `idx_upgrade_task_status` (`status`,`created_at`),
  KEY `idx_upgrade_task_manifest` (`manifest_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统升级任务';
CREATE TABLE `fun_system_migration` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `scope` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL,
  `checksum` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `executed_at` int unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_scope_version` (`scope`,`version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Migration执行记录';
SET FOREIGN_KEY_CHECKS=1;
